mapper.update:
		update STD_NBS_DOC set INFANT_STATENO = #{stateno}, patientId = #{climsPatientId, jdbcType=VARCHAR}, REVIEW_COMMENTS = REVIEW_COMMENTS ||'     ' ||#{p_reviewComments, jdbcType=VARCHAR},

CLIMS_MATCH_UID = #{p_worker_id}, CLIMS_MATCH_DT = sysdate, MEMO = 'MANUAL'
		 where document_id = #{p_documentId}

mapper.select:
select DOCUMENT_ID, 'N' MATCH_CD, 
	
	
	null FUZZY_CLUSTER_ID, DOCUMENT_ID CLUSTER_ID, '' POT_STATENO, 'CLIMS' DOC_TYPE
	
	from std_clims_doc where DOCUMENT_ID = #{documentId}

select DOCUMENT_ID, 'C' MATCH_CD, 


null FUZZY_CLUSTER_ID, DOCUMENT_ID CLUSTER_ID, POT_MOTHER_STATENO "POT_STATENO", 'NBS' DOC_TYPE

from STD_NBS_DOC where DOCUMENT_ID = #{documentId}
